bad = 0
for x in M:
    src = open(os.path.join(root, x["file"])).read()
    n = src.count(x["find"])
    if n != 1:
        print("find occurs %d times: %s (%s)" % (n, x["name"], x["file"]))
        bad += 1
if len({x["name"] for x in M}) != len(M):
    print("duplicate names"); bad += 1
if bad:
    raise SystemExit(1)
